void OmniboxAction::DestroyActive() {
  switch (tag_) {

    case Tag::kFocusChange:
      std::destroy_at(&data_.focus_change);
      break;
    case Tag::kTextInput:
      std::destroy_at(&data_.text_input);
      break;
    case Tag::kKey:
      std::destroy_at(&data_.key);
      break;
    case Tag::kPointer:
      std::destroy_at(&data_.pointer);
      break;
    case Tag::kDropText:
      std::destroy_at(&data_.drop_text);
      break;
    case Tag::kDropFile:
      std::destroy_at(&data_.drop_file);
      break;
    case Tag::kDragStart:
      std::destroy_at(&data_.drag_start);
      break;
  }
}

