// static
bool UnionTraits<::toolbar_ui_api::mojom::OmniboxAction::DataView, ::toolbar_ui_api::mojom::OmniboxActionPtr>::Read(
    ::toolbar_ui_api::mojom::OmniboxAction::DataView input,
    ::toolbar_ui_api::mojom::OmniboxActionPtr* output) {
  using UnionType = ::toolbar_ui_api::mojom::OmniboxAction;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kFocusChange: {
      ::toolbar_ui_api::mojom::OmniboxActionFocusChangePtr result_focus_change{};
      if (!input.ReadFocusChange(&result_focus_change))
        return false;

      *output = UnionType::NewFocusChange(
          std::move(result_focus_change));
      break;
    }
    case Tag::kTextInput: {
      ::toolbar_ui_api::mojom::OmniboxActionTextInputPtr result_text_input{};
      if (!input.ReadTextInput(&result_text_input))
        return false;

      *output = UnionType::NewTextInput(
          std::move(result_text_input));
      break;
    }
    case Tag::kKey: {
      ::toolbar_ui_api::mojom::OmniboxActionKeyPtr result_key{};
      if (!input.ReadKey(&result_key))
        return false;

      *output = UnionType::NewKey(
          std::move(result_key));
      break;
    }
    case Tag::kPointer: {
      ::toolbar_ui_api::mojom::OmniboxActionPointerPtr result_pointer{};
      if (!input.ReadPointer(&result_pointer))
        return false;

      *output = UnionType::NewPointer(
          std::move(result_pointer));
      break;
    }
    case Tag::kDropText: {
      ::toolbar_ui_api::mojom::OmniboxActionDropTextPtr result_drop_text{};
      if (!input.ReadDropText(&result_drop_text))
        return false;

      *output = UnionType::NewDropText(
          std::move(result_drop_text));
      break;
    }
    case Tag::kDropFile: {
      ::toolbar_ui_api::mojom::OmniboxActionDropFilePtr result_drop_file{};
      if (!input.ReadDropFile(&result_drop_file))
        return false;

      *output = UnionType::NewDropFile(
          std::move(result_drop_file));
      break;
    }
    case Tag::kDragStart: {
      ::std::monostate result_drag_start{};
      if (!input.ReadDragStart(&result_drag_start))
        return false;

      *output = UnionType::NewDragStart(
          std::move(result_drag_start));
      break;
    }
    default:

      return false;
  }
  return true;
}

